/**
 * Composable hiển thị một dòng giao dịch trong LazyColumn.
 * Hỗ trợ vuốt từ phải sang trái để xóa giao dịch.
 *
 * @param transaction     Dữ liệu dòng giao dịch
 * @param onDelete        Callback khi người dùng xác nhận xóa
 * @param modifier        Modifier tuỳ chỉnh
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TransactionItemRow(
    transaction: TransactionItem,
    onDelete: (() -> Unit)? = null,
    modifier: Modifier = Modifier
) {
    val amountColor = remember(transaction.amount) {
        if (transaction.amount >= 0) SuccessGreen else null
    }

    if (onDelete != null) {
        var showConfirmDialog by remember { mutableStateOf(false) }

        val dismissState = rememberSwipeToDismissBoxState(
            confirmValueChange = { value ->
                if (value == SwipeToDismissBoxValue.EndToStart) {
                    showConfirmDialog = true
                }
                false // luôn từ chối → item tự snap back, swipe lại được ngay
            },
            positionalThreshold = { totalDistance -> totalDistance * 0.35f }
        )

        // Dialog xác nhận xóa
        if (showConfirmDialog) {
            AlertDialog(
                onDismissRequest = { showConfirmDialog = false },
                title = { Text("Xóa giao dịch") },
                text = { Text("Bạn có chắc muốn xóa giao dịch \"${transaction.title}\" không? Hành động này không thể hoàn tác.") },
                confirmButton = {
                    TextButton(onClick = {
                        showConfirmDialog = false
                        onDelete()
                    }) {
                        Text("Xóa", color = MaterialTheme.colorScheme.error)
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showConfirmDialog = false }) {
                        Text("Hủy")
                    }
                }
            )
        }

        SwipeToDismissBox(
            state = dismissState,
            enableDismissFromStartToEnd = false,
            enableDismissFromEndToStart = true,
            backgroundContent = {
                // Nền đỏ + icon thùng rác hiện khi vuốt trái
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(Color(0xFFE53935))
                        .padding(end = 20.dp),
                    contentAlignment = Alignment.CenterEnd
                ) {
                    Icon(
                        imageVector = Icons.Default.Delete,
                        contentDescription = "Xóa giao dịch",
                        tint = Color.White,
                        modifier = Modifier.size(28.dp)
                    )
                }
            },
            modifier = modifier
        ) {
            TransactionRowContent(transaction = transaction, amountColor = amountColor)
        }
    } else {
        TransactionRowContent(
            transaction = transaction,
            amountColor = amountColor,
            modifier = modifier
        )
    }
}

